sections.content:
Stack(
children: [
Container(
width: 200,
height: 200,
color: Colors.blue,
),
Container(
width: 100,
height: 100,
color: Colors.red,
),
Container(
width: 50,
height: 50,
color: Colors.green,
),
],
)
// Синий внизу, красный посередине, зелёный сверху

Align({
this.alignment = Alignment.center,  // позиция child внутри Stack
this.widthFactor,                   // ширина = child.width × factor
this.heightFactor,                  // высота = child.height × factor
required Widget child,
})

Stack(
children: [
Container(
width: 300,
height: 300,
color: Colors.grey.shade300,
),

// По центру (по умолчанию)
Align(
alignment: Alignment.center,
child: Container(
width: 100,
height: 100,
color: Colors.red,
child: const Center(child: Text('Center')),
),
),

// Вверху слева
Align(
alignment: Alignment.topLeft,
child: Container(
width: 80,
height: 80,
color: Colors.green,
child: const Center(child: Text('TL')),
),
),

// Внизу справа
Align(
alignment: Alignment.bottomRight,
child: Container(
width: 80,
height: 80,
color: Colors.blue,
child: const Center(child: Text('BR')),
),
),
],
)

Stack(
children: [
Container(
width: 300,
height: 300,
color: Colors.grey.shade300,
),

// Ширина = ширина child × 2
Align(
widthFactor: 2,
child: Container(
width: 50,
height: 50,
color: Colors.red,
),
),
// Результат: контейнер шириной 100px, отцентрованный

// Высота = высота child × 2
Align(
heightFactor: 2,
child: Container(
width: 50,
height: 50,
color: Colors.blue,
),
),
// Результат: контейнер высотой 100px, отцентрованный
],
)

Center(
child: Container(
width: 100,
height: 100,
color: Colors.red,
child: const Text('По центру'),
),
)
// Эквивалентно:
// Align(
//   alignment: Alignment.center,
//   child: Container(...),
// )

Stack(
children: [
// Изображение
Image.asset(
'assets/hero.jpg',
width: 300,
height: 200,
fit: BoxFit.cover,
),

// Градиент снизу
Positioned(
left: 0,
right: 0,
bottom: 0,
child: Container(
height: 100,
decoration: BoxDecoration(
gradient: LinearGradient(
begin: Alignment.topCenter,
end: Alignment.bottomCenter,
colors: [Colors.transparent, Colors.black.withOpacity(0.7)],
),
),
),
),

// Текст поверх изображения
Positioned(
left: 16,
right: 16,
bottom: 16,
child: Column(
crossAxisAlignment: CrossAxisAlignment.start,
children: const [
Text(
'Заголовок',
style: TextStyle(color: Colors.white, fontSize: 20, fontWeight: FontWeight.bold),
),
SizedBox(height: 4),
Text(
'Описание',
style: TextStyle(color: Colors.white70, fontSize: 14),
),
],
),
),
],
)

Stack(
alignment: Alignment.center,
children: [
Container(
width: 100,
height: 100,
decoration: BoxDecoration(
color: Colors.blue,
shape: BoxShape.circle,
),
),
const Icon(Icons.add, color: Colors.white, size: 30),
],
)
